INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > IT-Arbeitsplätze im Kontext > Systemarchitekturen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind Systemarchitekturen entscheidend für die Leistungsfähigkeit eines IT-Arbeitsplatzes?', 2, '[{"text": "Ja", "correct": true, "because": "Bestimmen Effizienz und Funktionalität"}, {"text": "Nein", "correct": false, "because": "Architektur ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Arbeitsplatz ohne eine definierte Systemarchitektur effizient arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Architektur strukturiert Systeme"}, {"text": "Ja", "correct": false, "because": "Ohne Struktur ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Client-Server-Architektur nur für große Unternehmen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für kleine Netzwerke nutzbar"}, {"text": "Ja", "correct": false, "because": "Universell einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Cloud-basierte Systemarchitekturen die Flexibilität eines IT-Arbeitsplatzes erhöhen?', 2, '[{"text": "Ja", "correct": true, "because": "Ermöglicht Zugriff von überall"}, {"text": "Nein", "correct": false, "because": "Flexibilität wird gesteigert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Systemarchitekturen statisch und unveränderbar?', 2, '[{"text": "Nein", "correct": true, "because": "Können an Bedürfnisse angepasst werden"}, {"text": "Ja", "correct": false, "because": "Dynamisch anpassbar"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Systemarchitektur ist typisch für verteilte IT-Arbeitsplätze?', 3, '[{"text": "Client-Server", "correct": true, "because": "Ermöglicht zentrale Datenverarbeitung"}, {"text": "Standalone", "correct": false, "because": "Isoliert"}, {"text": "Peer-to-Peer", "correct": false, "because": "Dezentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Architektur bietet Skalierbarkeit für wachsende IT-Arbeitsplätze?', 2, '[{"text": "Cloud-Architektur", "correct": true, "because": "Flexibel erweiterbar"}, {"text": "Monolithisch", "correct": false, "because": "Weniger skalierbar"}, {"text": "Standalone", "correct": false, "because": "Eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Wahl einer Systemarchitektur entscheidend?', 2, '[{"text": "Anforderungen", "correct": true, "because": "Bestimmen Struktur"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferzeit", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Systemarchitektur eignet sich für unabhängige IT-Arbeitsplätze?', 3, '[{"text": "Standalone", "correct": true, "because": "Keine Netzwerkabhängigkeit"}, {"text": "Client-Server", "correct": false, "because": "Netzwerkbasiert"}, {"text": "Cloud", "correct": false, "because": "Internetabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil der Client-Server-Architektur?', 2, '[{"text": "Zentrale Verwaltung", "correct": true, "because": "Erleichtert Management"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht primär"}, {"text": "Minimale Wartung", "correct": false, "because": "Wartung erforderlich"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Systemarchitekturen werden an IT-Arbeitsplätzen genutzt?', 4, '[{"text": "Client-Server", "correct": true, "because": "Für Netzwerke"}, {"text": "Cloud", "correct": true, "because": "Für Flexibilität"}, {"text": "Standalone", "correct": true, "because": "Für Einzelplätze"}, {"text": "Farbarchitektur", "correct": false, "because": "Nicht existent"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Cloud-Architektur?', 3, '[{"text": "Skalierbarkeit", "correct": true, "because": "Anpassbar an Bedarf"}, {"text": "Flexibilität", "correct": true, "because": "Ortsunabhängig"}, {"text": "Kosteneffizienz", "correct": true, "because": "Pay-per-Use"}, {"text": "Minimale Leistung", "correct": false, "because": "Nicht zutreffend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Wahl der Systemarchitektur?', 3, '[{"text": "Anforderungen", "correct": true, "because": "Bestimmen Struktur"}, {"text": "Budget", "correct": true, "because": "Finanzielle Grenzen"}, {"text": "Netzwerkverfügbarkeit", "correct": true, "because": "Technische Voraussetzung"}, {"text": "Produktfarbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei Systemarchitekturen auftreten?', 4, '[{"text": "Komplexität", "correct": true, "because": "Erschwert Verwaltung"}, {"text": "Kosten", "correct": true, "because": "Hohe Investitionen"}, {"text": "Abhängigkeiten", "correct": true, "because": "Netzwerkprobleme"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale charakterisieren eine Standalone-Architektur?', 3, '[{"text": "Unabhängigkeit", "correct": true, "because": "Kein Netzwerk nötig"}, {"text": "Einfache Wartung", "correct": true, "because": "Weniger Komponenten"}, {"text": "Geringere Kosten", "correct": true, "because": "Keine Serverinfrastruktur"}, {"text": "Hohe Skalierbarkeit", "correct": false, "because": "Eingeschränkt"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Client-Server-Architekturen bieten zentrale Verwaltung. b) Cloud-Architekturen sind unflexibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Client-Server ja, Cloud flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Standalone-Architekturen sind netzwerkunabhängig. b) Systemarchitekturen sind unveränderbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Standalone ja, Architekturen anpassbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Cloud-Architekturen erhöhen die Flexibilität. b) Client-Server ist nur für große Unternehmen geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cloud ja, Client-Server universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Systemarchitekturen beeinflussen die Leistung. b) IT-Arbeitsplätze können ohne Architektur effizient sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leistung ja, Architektur nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Skalierbarkeit ist ein Vorteil der Cloud-Architektur. b) Standalone-Architekturen sind für verteilte Systeme ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Skalierbarkeit ja, Standalone ungeeignet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

